+            if (this == o) return true;
+            if (o == null || getClass() != o.getClass()) return false;
+            SnykDependencyNode that = (SnykDependencyNode) o;
+            return Objects.equals(nodeId, that.nodeId) && Objects.equals(pkgId, that.pkgId);
+        }
